import{_ as o,o as r,c as l,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const f=JSON.parse('{"title":"CDS Jewel -- Ceph 0 day for performance regression","description":"","frontmatter":{"title":"CDS Jewel -- Ceph 0 day for performance regression","date":"2015-08-04T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph性能回归","自动化性能测试","Ceph测试框架","Ceph性能优化","Ceph开发"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Ceph_0_day_for_performance_regression.md","filePath":"posts/2015/CDS_Jewel_--_Ceph_0_day_for_performance_regression.md","lastUpdated":1780459816000}'),_={name:"posts/2015/CDS_Jewel_--_Ceph_0_day_for_performance_regression.md"};function t(i,e,s,a,n,C){return r(),l("div",null,[...e[0]||(e[0]=[p("<p>Ceph分布式存储研发团队于2023年11月某日召开会议，主题为Ceph性能回归分析及改进。会议主要讨论了以下关键议题：</p><ol><li><p><strong>性能回归问题</strong>：</p><ul><li>分析了Ceph在性能方面的潜在回归问题，例如蜘蛛权限、鱼饼性能认证等。</li><li>发现某些性能改进可能产生了反效果，如Hammer版本更新后性能未如预期提升。</li><li>讨论了不同配置和硬件对性能的影响。</li></ul></li><li><p><strong>性能测试框架</strong>：</p><ul><li>讨论了如何构建自动化性能测试框架，用于评估Ceph的性能。</li><li>提出了使用测试集群进行基准测试，并收集系统性能数据（CPU、内存、磁盘I/O等）。</li><li>讨论了使用fio、Chef、Ghost等工具进行性能测试。</li></ul></li><li><p><strong>性能测试方法</strong>：</p><ul><li>讨论了使用SEF、小I/O基准测试等工具进行性能测试。</li><li>提出了将性能测试集成到Ceph的日常测试中，并使用Cot Vinci进行测试。</li></ul></li><li><p><strong>性能测试结果分析</strong>：</p><ul><li>讨论了如何分析性能测试结果，并找出性能回归的原因。</li><li>提出了使用Google Sheets等工具进行数据分析和可视化。</li></ul></li></ol><p>会议决定建立自动化性能测试框架，使用测试集群进行基准测试，并收集性能数据。同时，使用fio、Chef、Ghost等工具进行性能测试，将测试结果集成到Ceph的日常测试中。研发团队和集群管理员将共同分析性能测试结果，找出性能回归的原因，并定期进行性能测试以跟踪性能变化。</p><p>会议还讨论了使用SEF、小I/O基准测试等工具进行性能测试的便利性，以及将性能测试集成到Ceph的日常测试中的可行性。此外，还讨论了使用Google Sheets等工具进行数据分析和可视化的效果。</p>",4)])])}const d=o(_,[["render",t]]);export{f as __pageData,d as default};
